from taf.sw.neat.utils.get_return_data import get_return_data
from taf.sw.neat.httpclient.neat_uri import CloudURI
from taf.sw.neat.httpclient.ApiClientLocal import ApiClientLocal
from taf.internal.sw.neat.client.cloud_manager.v1.apis.tags.clouds_api import CloudsApi
from taf.internal.sw.neat.client.cloud_manager.v1.apis.tags.secrets_api import SecretsApi
from taf.internal.sw.neat.client.cloud_manager.v1.apis.tags.alarmfeed_api import AlarmfeedApi
from taf.internal.sw.neat.client.cloud_manager.v1.api_client import ApiClient
from taf.internal.sw.neat.client.cloud_manager.v1.configuration import Configuration
from taf.internal.sw.neat.client.cloud_manager.v1.apis.tags.health_api import HealthApi
from taf.internal.sw.neat.client.cloud_manager.v1.apis.tags.analytics_api import AnalyticsApi


class CloudManagerV1(object):
    def __init__(self, conn_details, access_token):
        self.conn_details = conn_details
        self.configuration = Configuration()
        self.configuration.verify_ssl = False
        self.configuration.host = conn_details.make_configuration_host(original_endpoint=self.configuration.get_host_from_settings(index=None))
        self.configuration.access_token = access_token
        api_client = ApiClient(configuration=self.configuration)
        self.api_client_local = ApiClientLocal(conn_details, access_token)

        self.cloud_api = CloudsApi(api_client)
        self.secrets_api = SecretsApi(api_client)
        self.alarm_api = AlarmfeedApi(api_client)
        self.health_api = HealthApi(api_client)
        self.alarm_analytics_api = AnalyticsApi(api_client)

    def get_cloud_resources(self, raw=False, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val

        res = self.cloud_api.clouds_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)

    def get_secrets_by_secretid(self, secret_id, fields=None, timeout=60):
        path_params = {'secretId': secret_id}
        query_params = {}
        if fields:
            query_params['fields'] = fields
        res_body = self.secrets_api.secrets_secret_id_get(query_params=query_params, path_params=path_params, timeout=timeout).body
        return res_body['data']['attributes']

    def get_all_alarms(self, timeout=60):
        res_body = self.alarm_api.alarmfeed_get(timeout=timeout).body
        return res_body['data']['attributes']['alarmfeed']

    def delete_cloud_instance(self, cloud_id, timeout=60):
        return self.cloud_api.clouds_cloud_id_delete(path_params={'cloudId': cloud_id}, timeout=timeout)

    def modify_cloud_resources(self, cloud_id, raw=True, timeout=60, **kwargs):
        if not kwargs:
            raise ValueError("At least one parameter should be provided to update")
        body = {
                "data": {
                    "type": "clouds",
                    "id": cloud_id,
                    "attributes": {
                    }
                }
            }
        for item_key, item_value in kwargs.items():
            if item_key in ["currentPassword", "newPassword"]:
                if "passwordChange" in body['data']['attributes']:
                    body['data']['attributes']["passwordChange"][item_key] = item_value
                else:
                    body['data']['attributes']["passwordChange"] = {item_key: item_value}
            else:
                body['data']['attributes'][item_key] = item_value
        res= self.cloud_api.clouds_cloud_id_patch(path_params={'cloudId': cloud_id}, body=body, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)["data"]

    def create_cloud_resource(self, raw=True, timeout=60, **kwargs):
        body = {
            "data":{
                "type":"clouds",
                "attributes": kwargs
                }
            }
        res = self.cloud_api.clouds_post(content_type="application/json",body=body, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)["data"]

    def get_cloud_manager_health(self, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.health_api.admin_health_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)['data']

    def get_active_cloud_alarms(self, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.alarm_analytics_api.analytics_alarms_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)

    def get_alarm_analytics(self, *, fields="", groups="", clouds="", alarmids="", severity="", before="",
                            after="", timeout=60):
        query_params = {}
        params = {
            'fields': fields,
            'groups': groups,
            'clouds': clouds,
            'alarmids': alarmids,
            'severity': severity,
            'before': before,
            'after': after,
        }
        query_params.update({k: v for k, v in params.items() if v})
        res = self.api_client_local.send_get_request(uri=f"{CloudURI.analytics_uri}", params=query_params,
                                                     timeout=timeout)
        return get_return_data(res)
